// 插件与统一约定（java-library/maven-publish/jacoco、发布与测试机制）由根 build.gradle.kts 的 subprojects 块授予
dependencies {
    api(project(":turboweb-common"))
    // 线程池契约与弹性实现由 turboweb-concurrent 提供；ThreadPool 出现在本模块公开签名（调度器与响应策略构造参数），用 api 暴露
    api(project(":turboweb-concurrent"))
    // JSON 序列化器契约与 Jackson 实现由 turboweb-serializer 提供；JsonSerializer 出现在本模块公开签名（Builder 与上下文、响应类构造参数），用 api 暴露
    api(project(":turboweb-serializer"))
    // 服务器线程模型直接使用 netty（http/websocketx 与 http2 编解码），响应写出使用 reactor-core，均不涉 reactor-netty 本体；URI 查询解析由仓内 core.helper 自实现
    api(libs.netty.codec.http)
    api(libs.netty.codec.http2)
    api(libs.reactor.core)
    // 参数绑定与路由注解、上下文消息契约与媒体类型由 turboweb-rest-api 提供
    api(project(":turboweb-rest-api"))
    // Bean 校验器契约由 turboweb-validation 提供；BeanValidator 出现在绑定接口与路由处理器公开签名，用 api 暴露
    api(project(":turboweb-validation"))
    // 服务器运行时契约由 turboweb-server-runtime 提供；ServerRuntime 出现在应用管理器注册方法与服务器注册的公开签名，用 api 暴露
    api(project(":turboweb-server-runtime"))
    // 聚合turboweb-websocket模块
    api(project(":turboweb-websocket"))
    implementation(project(":turboweb-struct"))
    // Gradle 9 不再自带 platform launcher；BOM 复用既有的 junit-jupiter 版本号，不引入第二个需要手工同步的版本
    testImplementation(platform(libs.junit.bom))
    testImplementation(libs.junit.jupiter)
    testRuntimeOnly(libs.junit.platform.launcher)
    testRuntimeOnly(libs.logback.classic)
}

description = "turboweb-http"

// http-server 覆盖率门禁（阶段 4 开闸）：整模块零排除，行覆盖 ≥ 0.80
// ——闸线 0.90→0.80 为 2026-10-07 用户终裁，接入 check（spec §10 阶段 4 / §11.1）
tasks.named<org.gradle.testing.jacoco.tasks.JacocoCoverageVerification>("jacocoTestCoverageVerification") {
    dependsOn(tasks.named("test"))
    violationRules {
        rule {
            limit {
                counter = "LINE"
                minimum = "0.80".toBigDecimal()
            }
        }
    }
}
tasks.named("check") {
    dependsOn(tasks.named("jacocoTestCoverageVerification"))
}

// PITest 变异作用域与覆盖率闸同形：整模块零排除
configure<info.solidsoft.gradle.pitest.PitestPluginExtension> {
    targetClasses.set(listOf("top.turboweb.http.*"))
}
